<script>
const tradition=<?= json_encode($tradition) ?>,book=<?= json_encode($book) ?>,locale=<?= json_encode($locale) ?>,bookSelect=document.getElementById('book-select'),chapterSelect=document.getElementById('chapter-select');try{if(book){const bookLabel=bookSelect?.selectedOptions[0]?.textContent||book;localStorage.setItem('dailybreath.lastReading',JSON.stringify({tradition,book,chapter:<?= (int)$chapter ?>,locale,label:<?= json_encode($readerTitle) ?>,translation:<?= json_encode($translation) ?>}))}}catch{}bookSelect.onchange=()=>location.href='?tradition='+tradition+'&book='+encodeURIComponent(bookSelect.value)+'&chapter=1&lang='+locale+'#reader-top';if(chapterSelect)chapterSelect.onchange=()=>location.href='?tradition='+tradition+'&book='+encodeURIComponent(book)+'&chapter='+chapterSelect.value+'&lang='+locale+'#reader-top';
const annotationKey='dailybreath.verseAnnotations',annotations=(()=>{try{return JSON.parse(localStorage.getItem(annotationKey)||'{}')}catch(e){return{}}})(),save=()=>localStorage.setItem(annotationKey,JSON.stringify(annotations));document.querySelectorAll('.verse-tools').forEach(tools=>{const key=tools.dataset.for,verse=document.querySelector(`[data-verse-key="${CSS.escape(key)}"]`),favorite=tools.querySelector('.favorite'),highlight=tools.querySelector('.highlight'),note=tools.querySelector('.note');const render=()=>{const item=annotations[key]||{};favorite.classList.toggle('active',!!item.favorite);favorite.textContent=item.favorite?'♥ Saved':'♡ Save';highlight.classList.toggle('active',!!item.highlight);verse.dataset.highlight=item.highlight||'';document.querySelector(`[data-note-for="${CSS.escape(key)}"]`)?.remove();if(item.note){const el=document.createElement('div');el.className='verse-note';el.dataset.noteFor=key;el.textContent=item.note;tools.after(el)}note.classList.toggle('active',!!item.note)};favorite.onclick=()=>{annotations[key]={...(annotations[key]||{}),favorite:!annotations[key]?.favorite};save();render()};highlight.onclick=()=>{const current=annotations[key]?.highlight||'',next=current===''?'gold':current==='gold'?'green':'';annotations[key]={...(annotations[key]||{}),highlight:next};save();render()};note.onclick=()=>{const value=prompt('Private note stored on this browser:',annotations[key]?.note||'');if(value===null)return;annotations[key]={...(annotations[key]||{}),note:value.trim()};save();render()};render()});
const guideChat=document.getElementById('guide-chat'),guideChatOpen=document.getElementById('open-guide-chat'),guideChatClose=document.getElementById('close-guide-chat'),guideChatForm=document.getElementById('guide-chat-form'),guideChatInput=document.getElementById('guide-chat-input'),guideChatMessages=document.getElementById('guide-chat-messages');
const guideChatSuggestions=document.getElementById('guide-chat-suggestions');['Help me understand this passage','How can I build a steady prayer habit?','What is one small step I can take today?'].forEach(text=>{const button=document.createElement('button');button.type='button';button.textContent=text;button.onclick=()=>{guideChatInput.value=text;guideChatInput.focus()};guideChatSuggestions.append(button)});
let guideChatHistory=[];let jaguarNonce=<?= json_encode($jaguarNonce) ?>,jaguarNonceIssuedAt=<?= json_encode($jaguarNonceIssuedAt) ?>,jaguarNonceSignature=<?= json_encode($jaguarNonceSignature) ?>;
const addGuideChatMessage=(role,text)=>{const message=document.createElement('p');message.className='guide-chat-message '+role;message.textContent=text;guideChatMessages.append(message);guideChatMessages.scrollTop=guideChatMessages.scrollHeight;return message};
const guestProof=async()=>{const response=await fetch('/ai/api/challenge.php',{credentials:'same-origin',cache:'no-store'}),data=await response.json();if(!response.ok||!data.challenge)throw new Error(data.error||'The local security check is unavailable.');const zeros=Math.ceil(Number(data.difficulty)/4);for(let counter=0;counter<1000000000;counter++){const bytes=new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(`${data.challenge}:${counter}`)));let valid=true;for(let i=0;i<zeros;i++){if((i%2?bytes[Math.floor(i/2)]&15:bytes[Math.floor(i/2)]>>4)!==0){valid=false;break}}if(valid)return{challenge:data.challenge,counter:String(counter)};if(counter%500===0)await new Promise(resolve=>setTimeout(resolve,0))}throw new Error('The local security check could not complete.')};
guideChatOpen.onclick=()=>{guideChat.hidden=false;guideChatInput.focus()};guideChatClose.onclick=()=>{guideChat.hidden=true};guideChat.addEventListener('click',event=>{if(event.target===guideChat)guideChat.hidden=true});if(new URLSearchParams(location.search).get('chat')==='1')guideChatOpen.click();
guideChatForm.addEventListener('submit',async event=>{event.preventDefault();const text=guideChatInput.value.trim();if(!text)return;guideChatInput.value='';guideChatHistory.push({role:'user',content:text});addGuideChatMessage('user',text);const pending=addGuideChatMessage('assistant','<?= e($jaguarGuide) ?> is thinking…');try{const response=await fetch('api/jaguar-chat.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':<?= json_encode($jaguarCsrf) ?>},body:JSON.stringify({mode:'core',language:locale,guide:<?= json_encode($jaguarGuideKey) ?>,messages:guideChatHistory,nonce:jaguarNonce,nonce_issued_at:jaguarNonceIssuedAt,nonce_signature:jaguarNonceSignature,proof:await guestProof()})});const nextNonce=response.headers.get('X-Jaguar-Nonce'),nextIssuedAt=response.headers.get('X-Jaguar-Nonce-Issued-At'),nextSignature=response.headers.get('X-Jaguar-Nonce-Signature');if(nextNonce&&nextIssuedAt&&nextSignature){jaguarNonce=nextNonce;jaguarNonceIssuedAt=Number(nextIssuedAt);jaguarNonceSignature=nextSignature}const data=await response.json();if(!response.ok)throw new Error(data.error||'Jaguar is unavailable.');pending.textContent=data.message;guideChatHistory.push({role:'assistant',content:data.message})}catch(error){pending.textContent=error instanceof Error?error.message:'Jaguar is unavailable.'}});
</script>
<?= dailybreath_web_scripts() ?><script src="/assets/js/visitor-analytics.js" defer></script></body></html>
